import warnings
import numpy as np
import pytest
import pyhf


def test_oracle_001():
    """numpy_backend should expose array_type as a class attribute equal to np.ndarray."""
    from pyhf.tensor.numpy_backend import numpy_backend

    # Before patch: numpy_backend has no array_type attribute -> AttributeError / missing
    # After patch: numpy_backend.array_type is np.ndarray
    assert hasattr(numpy_backend, 'array_type'), (
        "numpy_backend should have an 'array_type' class attribute"
    )
    assert numpy_backend.array_type is np.ndarray


def test_oracle_002():
    """numpy_backend should expose array_subtype as a class attribute equal to np.number."""
    from pyhf.tensor.numpy_backend import numpy_backend

    # Before patch: numpy_backend has no array_subtype attribute
    # After patch: numpy_backend.array_subtype is np.number
    assert hasattr(numpy_backend, 'array_subtype'), (
        "numpy_backend should have an 'array_subtype' class attribute"
    )
    assert numpy_backend.array_subtype is np.number


def test_oracle_003():
    """pyhf.schema.validate should accept numpy arrays as valid 'array' types in a model spec."""
    # Build a minimal valid model spec where data fields are numpy arrays instead of plain lists
    spec = {
        "channels": [
            {
                "name": "ch1",
                "samples": [
                    {
                        "name": "signal",
                        "data": np.array([12.0, 11.0]),
                        "modifiers": [
                            {"name": "mu", "type": "normfactor", "data": None}
                        ],
                    },
                    {
                        "name": "background",
                        "data": np.array([50.0, 52.0]),
                        "modifiers": [
                            {
                                "name": "uncorr_bkguncrt",
                                "type": "shapesys",
                                "data": np.array([3.0, 7.0]),
                            }
                        ],
                    },
                ],
            }
        ]
    }

    # Before patch: raises InvalidSpecification because numpy arrays are not recognised
    #               as valid JSON-schema "array" type.
    # After patch:  passes without exception.
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", DeprecationWarning)
        try:
            pyhf.schema.validate(spec, "model.json")
        except pyhf.exceptions.InvalidSpecification as exc:
            # Only fail if the error is about array type – not some other schema issue
            if "is not of type 'array'" in str(exc):
                pytest.fail(
                    f"pyhf.schema.validate raised InvalidSpecification for a spec "
                    f"containing numpy arrays (tensor support not implemented): {exc}"
                )
            raise

