def _find_conf_py():
    # Search for docs/conf.py relative to this file or common repo roots
    here = pathlib.Path(__file__).resolve().parent
    # Walk up looking for docs/conf.py
    for parent in [here] + list(here.parents):
        candidate = parent / 'docs' / 'conf.py'
        if candidate.exists():
