import pyhf.writexml as writexml


def _make_spec_no_inits():
    """Workspace spec with parameter config that has bounds but NO inits."""
    return {
        "channels": [
            {
                "name": "ch",
                "samples": [
                    {
                        "data": [1000.0],
                        "modifiers": [
                            {"data": None, "name": "mu_sig", "type": "normfactor"},
                            {
                                "data": {"hi": 1.5, "lo": 0.5},
                                "name": "unc",
                                "type": "normsys",
                            },
                        ],
                        "name": "signal",
                    }
                ],
            }
        ],
        "measurements": [
            {
                "config": {
                    "parameters": [
                        {
                            "name": "mu_sig",
                            "bounds": [[0, 10]],
                            # NOTE: no 'inits' key — this is the bug trigger
                        }
                    ],
                    "poi": "mu_sig",
                },
                "name": "meas",
            }
        ],
        "observations": [{"data": [1000], "name": "ch"}],
        "version": "1.0.0",
    }


def test_oracle_001():
    """build_modifier must not raise KeyError when 'inits' is absent but 'bounds' is present."""
    spec = _make_spec_no_inits()
    modifierspec = {"data": None, "name": "mu_sig", "type": "normfactor"}
    sampledata = [1000.0]
    # Should not raise KeyError: 'inits'
    result = writexml.build_modifier(spec, modifierspec, "ch", "signal", sampledata)
    assert result is not None


def test_oracle_002():
    """build_modifier with no inits should fall back to default val=1."""
    spec = _make_spec_no_inits()
    modifierspec = {"data": None, "name": "mu_sig", "type": "normfactor"}
    sampledata = [1000.0]
    result = writexml.build_modifier(spec, modifierspec, "ch", "signal", sampledata)
    # Default val is 1; the element should have Val="1"
    assert result.get('Val') == '1'


def test_oracle_003():
    """build_modifier with no inits should still use the specified bounds."""
    spec = _make_spec_no_inits()
    modifierspec = {"data": None, "name": "mu_sig", "type": "normfactor"}
    sampledata = [1000.0]
    result = writexml.build_modifier(spec, modifierspec, "ch", "signal", sampledata)
    # bounds [[0, 10]] -> Low="0", High="10"
    assert result.get('Low') == '0'
    assert result.get('High') == '10'

import pathlib
import ast

CONF_PY = pathlib.Path(__file__).parent / "docs" / "conf.py"


def _read_extensions():
    """Parse docs/conf.py and return the list of strings in the 'extensions' variable."""
    source = CONF_PY.read_text()
    tree = ast.parse(source)
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "extensions":
                    if isinstance(node.value, ast.List):
                        result = []
                        for elt in node.value.elts:
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                result.append(elt.value)
                        return result
    return []


def test_oracle_001():
    """sphinx_rtd_theme must appear in the extensions list in docs/conf.py."""
    extensions = _read_extensions()
    assert "sphinx_rtd_theme" in extensions, (
        "sphinx_rtd_theme is not listed in the extensions in docs/conf.py"
    )


def test_oracle_002():
    """sphinx_rtd_theme must be explicitly present so RTD theme JS/CSS loads correctly."""
    source = CONF_PY.read_text()
    assert "'sphinx_rtd_theme'" in source or '"sphinx_rtd_theme"' in source, (
        "sphinx_rtd_theme string not found anywhere in docs/conf.py"
    )


def test_oracle_003():
    """The extensions list in docs/conf.py must contain sphinx_rtd_theme as a member."""
    extensions = _read_extensions()
    # Before the patch this list does not contain sphinx_rtd_theme
    missing = "sphinx_rtd_theme" not in extensions
    assert not missing, (
        f"sphinx_rtd_theme missing from extensions; found: {extensions}"
    )

import uproot
import uproot.containers
import uproot.extras
import uproot.interpretation.objects


def test_oracle_001():
    """AsDynamic.awkward_form must return the model form directly, not wrapped in ListOffsetForm."""
    awkward = uproot.extras.awkward()

    class MockModel:
        __name__ = "Model_TVector3_v3"

        @classmethod
        def awkward_form(cls, file, context):
            return awkward.forms.NumpyForm("float64")

    container = uproot.containers.AsDynamic(model=MockModel)
    context = {
        "index_format": "i64",
        "header": True,
        "tobject_header": True,
        "breadcrumbs": (),
    }

    form = container.awkward_form(None, context)

    # Before fix: form was ListOffsetForm(index_format, model_form)
    # After fix:  form is model_form directly
    assert not isinstance(
        form, awkward.forms.ListOffsetForm
    ), "AsDynamic.awkward_form should not wrap result in ListOffsetForm"


def test_oracle_002():
    """AsDynamic.awkward_form must return exactly the form produced by the model."""
    awkward = uproot.extras.awkward()

    expected_form = awkward.forms.RecordForm(
        [awkward.forms.NumpyForm("float32")] * 3,
        ["fX", "fY", "fZ"],
    )

    class MockTVector3Model:
        __name__ = "Model_TVector3_v3"

        @classmethod
        def awkward_form(cls, file, context):
            return expected_form

    container = uproot.containers.AsDynamic(model=MockTVector3Model)
    context = {
        "index_format": "i64",
        "header": True,
        "tobject_header": True,
        "breadcrumbs": (),
    }

    form = container.awkward_form(None, context)

    assert form is expected_form, (
        "AsDynamic.awkward_form should return the model's form unchanged, "
        f"but got {type(form)}"
    )


def test_oracle_003():
    """AsDynamic.awkward_form with a record-like model must not produce a ListOffsetForm at the top level."""
    awkward = uproot.extras.awkward()

    class MockVectorModel:
        __name__ = "Model_TLorentzVector_v4"

        @classmethod
        def awkward_form(cls, file, context):
            return awkward.forms.RecordForm(
                [awkward.forms.NumpyForm("float64")] * 4,
                ["fX", "fY", "fZ", "fT"],
            )

    container = uproot.containers.AsDynamic(model=MockVectorModel)
    context = {
        "index_format": "i64",
        "header": True,
        "tobject_header": True,
        "breadcrumbs": (),
    }

    form = container.awkward_form(None, context)

    # The top-level form must be a RecordForm (matching the model), not a ListOffsetForm
    assert isinstance(form, awkward.forms.RecordForm), (
        f"Expected RecordForm from AsDynamic.awkward_form, got {type(form).__name__}"
    )
    assert not isinstance(form, awkward.forms.ListOffsetForm)

import uproot
import uproot._util
import fsspec
from unittest.mock import patch, MagicMock


def test_oracle_001():
    """String-style xrootd glob: fsspec.open_files must NOT receive the :ObjectName suffix."""
    captured_paths = []

    mock_file = MagicMock()
    mock_file.full_name = "root://server//store/data/run1/file.root"

    def mock_open_files(path, **kwargs):
        captured_paths.append(path)
        return [mock_file]

    with patch.object(fsspec, "open_files", side_effect=mock_open_files):
        try:
            uproot._util.regularize_files(
                "root://server//store/data/*/*.root:Events",
                steps_allowed=False,
            )
        except Exception:
            pass

    # Before the fix, fsspec.open_files received the full string with ':Events'.
    # After the fix, it receives only the file path (no object suffix).
    for path in captured_paths:
        assert ":Events" not in path, (
            f"Bug: fsspec.open_files received object path suffix: {path!r}"
        )


